var e={version:1,asset_id:`08a64f9e-b2bd-46b9-8ff6-30b758c910af`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/08a64f9e-b2bd-46b9-8ff6-30b758c910af/cabeza-ahora.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/08a64f9e-b2bd-46b9-8ff6-30b758c910af/cabeza-ahora.webp`,original_filename:`cabeza-ahora.webp`,size:169628,content_type:`image/webp`,created_at:`2026-10-02T15:37:50Z`},t={version:1,asset_id:`0fb26d44-c827-4cbe-963a-94e99e7a5f09`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/0fb26d44-c827-4cbe-963a-94e99e7a5f09/saco-y-organizo.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/0fb26d44-c827-4cbe-963a-94e99e7a5f09/saco-y-organizo.webp`,original_filename:`saco-y-organizo.webp`,size:183092,content_type:`image/webp`,created_at:`2026-10-02T15:37:53Z`},n={version:1,asset_id:`f2c41dd9-2171-4d41-be64-e2215f083ca9`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/f2c41dd9-2171-4d41-be64-e2215f083ca9/mes-en-fotos.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/f2c41dd9-2171-4d41-be64-e2215f083ca9/mes-en-fotos.webp`,original_filename:`mes-en-fotos.webp`,size:217894,content_type:`image/webp`,created_at:`2026-10-02T15:37:56Z`},r={version:1,asset_id:`d2655858-c985-4461-9724-8c482bc7339d`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/d2655858-c985-4461-9724-8c482bc7339d/sol-del-mes.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/d2655858-c985-4461-9724-8c482bc7339d/sol-del-mes.webp`,original_filename:`sol-del-mes.webp`,size:176922,content_type:`image/webp`,created_at:`2026-10-02T15:37:58Z`},i={version:1,asset_id:`a2196399-6301-4313-b3ac-75dba772b870`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/a2196399-6301-4313-b3ac-75dba772b870/rabia.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/a2196399-6301-4313-b3ac-75dba772b870/rabia.webp`,original_filename:`rabia.webp`,size:290522,content_type:`image/webp`,created_at:`2026-10-02T15:38:02Z`},a={version:1,asset_id:`af687926-16c3-4aee-a10a-e2189ce953fb`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/af687926-16c3-4aee-a10a-e2189ce953fb/demora.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/af687926-16c3-4aee-a10a-e2189ce953fb/demora.webp`,original_filename:`demora.webp`,size:216856,content_type:`image/webp`,created_at:`2026-10-02T15:38:06Z`},o={version:1,asset_id:`7602cc12-9b78-4213-9305-df23ba8d7662`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/7602cc12-9b78-4213-9305-df23ba8d7662/aprender.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/7602cc12-9b78-4213-9305-df23ba8d7662/aprender.webp`,original_filename:`aprender.webp`,size:220876,content_type:`image/webp`,created_at:`2026-10-02T15:38:09Z`},s={version:1,asset_id:`9294817d-ac61-4a77-adf5-f9a878a12f86`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/9294817d-ac61-4a77-adf5-f9a878a12f86/resuelto.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/9294817d-ac61-4a77-adf5-f9a878a12f86/resuelto.webp`,original_filename:`resuelto.webp`,size:229680,content_type:`image/webp`,created_at:`2026-10-02T15:38:13Z`},c={version:1,asset_id:`f3391477-fd19-45e5-9da7-d29bc01f5838`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/f3391477-fd19-45e5-9da7-d29bc01f5838/ocurrencias.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/f3391477-fd19-45e5-9da7-d29bc01f5838/ocurrencias.webp`,original_filename:`ocurrencias.webp`,size:208696,content_type:`image/webp`,created_at:`2026-10-02T15:38:18Z`},l={version:1,asset_id:`63d6a704-8a20-47b6-89c0-89ad0c60a223`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/63d6a704-8a20-47b6-89c0-89ad0c60a223/agradecida.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/63d6a704-8a20-47b6-89c0-89ad0c60a223/agradecida.webp`,original_filename:`agradecida.webp`,size:190958,content_type:`image/webp`,created_at:`2026-10-02T15:38:24Z`},u={version:1,asset_id:`c6aa0bf9-0d00-44c8-8cb2-d0536fb0296d`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/c6aa0bf9-0d00-44c8-8cb2-d0536fb0296d/espacio-hoy.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/c6aa0bf9-0d00-44c8-8cb2-d0536fb0296d/espacio-hoy.webp`,original_filename:`espacio-hoy.webp`,size:173722,content_type:`image/webp`,created_at:`2026-10-02T15:38:27Z`},d={version:1,asset_id:`fb3ae86c-7903-4592-8314-27c62b89df92`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/fb3ae86c-7903-4592-8314-27c62b89df92/recordatorio.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/fb3ae86c-7903-4592-8314-27c62b89df92/recordatorio.webp`,original_filename:`recordatorio.webp`,size:190244,content_type:`image/webp`,created_at:`2026-10-02T15:38:30Z`},f={version:1,asset_id:`3880d1f5-681b-4765-bd49-d5a76eb34e38`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/3880d1f5-681b-4765-bd49-d5a76eb34e38/ahora-observo.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/3880d1f5-681b-4765-bd49-d5a76eb34e38/ahora-observo.webp`,original_filename:`ahora-observo.webp`,size:181534,content_type:`image/webp`,created_at:`2026-10-02T15:38:34Z`},p={version:1,asset_id:`40b2cd4f-4e20-4c1a-ad0b-f2e6652d0980`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/40b2cd4f-4e20-4c1a-ad0b-f2e6652d0980/logro-ansiedad.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/40b2cd4f-4e20-4c1a-ad0b-f2e6652d0980/logro-ansiedad.webp`,original_filename:`logro-ansiedad.webp`,size:196108,content_type:`image/webp`,created_at:`2026-10-02T15:38:37Z`},m={version:1,asset_id:`e71cb6e8-3e85-4faa-8d37-30fce94a4779`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/e71cb6e8-3e85-4faa-8d37-30fce94a4779/decidir-me-hace-bien.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/e71cb6e8-3e85-4faa-8d37-30fce94a4779/decidir-me-hace-bien.webp`,original_filename:`decidir-me-hace-bien.webp`,size:170924,content_type:`image/webp`,created_at:`2026-10-02T15:38:40Z`},h=[{slug:`carta-de-despedida`,title:`Carta de despedida que no necesitás enviar`,tagline:`Para cuando hay cosas que necesitás decir aunque la otra persona nunca las lea.`,image:{version:1,asset_id:`2a009c7c-8d56-42eb-b021-379dbbdebe9a`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/2a009c7c-8d56-42eb-b021-379dbbdebe9a/nuevo-1.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/2a009c7c-8d56-42eb-b021-379dbbdebe9a/nuevo-1.webp`,original_filename:`nuevo-1.webp`,size:169858,content_type:`image/webp`,created_at:`2026-10-02T16:27:00Z`}.url,category:`escribir`,categoryLabel:`Cerrar ciclos`,topics:[`emociones`,`cerrar`],duration:`15–30 min`,minutes:20,accent:`rosa`,intro:[`Puede acompañarte cuando quedó una conversación pendiente, terminó una relación o cambió una etapa. No busca conseguir una respuesta ni decidir si retomar contacto: es un lugar para expresar lo que todavía necesitás decir.`,`Podés escribirle a una persona, amistad, trabajo, expectativa, etapa o versión anterior de vos.`],what:`Vas a escribir una carta que no necesitás enviar, haciendo lugar tanto a lo que dolió como a lo que aprendiste.`,before:[`Buscá un momento sin apuro ni mensajes que responder enseguida. No tenés que escribir ‘bien’ ni ser justa con todas las partes mientras explorás tu experiencia.`,`La carta es para vos. No necesita enviarse.`],steps:[`Arriba de la hoja escribí ‘Todo lo que nunca dije’ o ‘Carta de despedida’.`,`Empezá libremente: ‘Lo que más me dolió fue…’, ‘Hay algo que nunca pude decirte…’, ‘Me hubiese gustado…’, ‘También agradezco…’.`,`Armá cuatro apartados: LO QUE ME DOLIÓ · LO QUE NO PUDE DECIR · LO QUE APRENDÍ · LO QUE HOY ELIJO SOLTAR.`,`No fabriques una conclusión positiva. Podés terminar reconociendo cómo te sentís.`,`Si querés, cerrá con una frase propia: ‘Esto fue importante para mí y también terminó’ o ‘Me llevo lo aprendido y sigo’. Guardar, romper, triturar, descartar, archivar o releer la carta más adelante son opciones; el gesto simbólico es opcional.`],questions:[`¿Qué necesitaba que entendiera?`,`¿Qué me dolió realmente?`,`¿Qué parte todavía intento cambiar mentalmente?`,`¿Qué esperaba que ocurriera?`,`¿Qué nunca pude expresar?`,`¿Qué aprendí sobre mí?`,`¿Qué límite necesito?`,`¿Qué me gustaría dejar de cargar?`,`¿Qué puedo conservar de esa experiencia sin conservar el vínculo?`],after:[`¿Qué parte de la carta necesitaba escribir hace tiempo?`,`¿Qué emoción apareció con más fuerza?`,`¿Hay algo que ahora veo de otra manera?`,`¿Qué necesito ahora: descansar, hablar con alguien, caminar o guardar la carta?`],why:[`Poner experiencias significativas en palabras puede facilitar su organización narrativa y permitir mirarlas con algo de distancia.`,`La escritura expresiva no siempre alivia inmediatamente; a veces acerca emociones intensas. El objetivo es poder observar y articular la experiencia.`],yourWay:[`Escribí una carta tradicional o solamente diez líneas.`,`Hacé cuatro bloques, frases sueltas o un collage.`,`Dibujá entre medio o pegá una foto de esa etapa.`,`Escribile a una versión anterior de vos.`],note:`Si escribir sobre esto te resulta demasiado intenso, podés parar. No necesitás terminarlo de una sola vez.`},{slug:`cosas-que-me-hacen-vibrar-el-corazon`,title:`Cosas que me hacen vibrar el corazón`,tagline:`Para recordar qué cosas te hacen sentir más conectada con la vida.`,image:{version:1,asset_id:`f31c7aa3-91db-4df7-9d4a-bc2030684730`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/f31c7aa3-91db-4df7-9d4a-bc2030684730/nuevo-2.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/f31c7aa3-91db-4df7-9d4a-bc2030684730/nuevo-2.webp`,original_filename:`nuevo-2.webp`,size:153990,content_type:`image/webp`,created_at:`2026-10-02T16:27:03Z`}.url,category:`crear`,categoryLabel:`Autoconocimiento`,topics:[`conocerme`,`creatividad`],duration:`10–20 min`,minutes:15,accent:`amarillo`,intro:[`Buscá actividades, personas, lugares y experiencias que te despiertan interés, disfrute o curiosidad. No tienen que ser grandes pasiones: leer, bailar, caminar, cocinar o mirar el cielo también cuentan.`],what:`Vas a dibujar un corazón rodeado de todo eso que te conecta con lo que disfrutás.`,before:[`Pensá en cómo te sentís al hacer algo, no en si sos buena haciéndolo.`],steps:[`Dibujá un corazón en el centro: anatómico, simple o abstracto.`,`Trazá líneas hacia afuera.`,`En cada línea escribí algo que te dé curiosidad, alegría, conexión, presencia, energía o interés.`,`Si aparece ‘¿soy buena en esto?’, cambiá la pregunta por ‘¿cómo me siento cuando lo hago?’.`,`Elegí tres y marcá ‘♡ QUIERO MÁS DE ESTO’.`],questions:[`¿Qué podría hacer durante horas?`,`¿Qué siempre termino fotografiando?`,`¿Qué conversaciones disfruto?`,`¿Dónde el tiempo pasa diferente?`,`¿Qué hacía cuando era más chica?`,`¿Qué me despierta curiosidad?`,`¿Qué temas siempre vuelvo a buscar?`,`¿Qué me hace sentir más yo?`],after:[`¿Qué aparece varias veces?`,`¿Qué dejé de hacer últimamente?`,`¿Qué podría recuperar esta semana?`,`¿Qué disfruto aunque ‘no sirva para nada’?`],why:[`Explorar actividades valiosas puede aclarar preferencias, fuentes personales de motivación y valores.`,`También ayuda a distinguir lo que hacemos por obligación de lo que elegimos porque tiene significado para nosotras.`],yourWay:[`Usá recortes en lugar de palabras.`,`Hacé un corazón de papel pegado sobre la hoja.`,`Elegí solo tres cosas y dibujalas.`]},{slug:`reescribir-la-historia`,title:`Reescribir la historia: mirar la versión completa`,tagline:`Para cuando tu mente está recordando solamente una parte de lo que pasó.`,image:{version:1,asset_id:`a0f24642-56ef-4ac9-9218-4eaaf3e8a30b`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/a0f24642-56ef-4ac9-9218-4eaaf3e8a30b/nuevo-3.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/a0f24642-56ef-4ac9-9218-4eaaf3e8a30b/nuevo-3.webp`,original_filename:`nuevo-3.webp`,size:130938,content_type:`image/webp`,created_at:`2026-10-02T16:27:07Z`}.url,category:`escribir`,categoryLabel:`Perspectiva`,topics:[`emociones`,`cerrar`],duration:`15 min`,minutes:15,accent:`lila`,intro:[`Después de una ruptura, una amistad terminada o una decisión, podemos recordar solamente lo hermoso, lo malo, lo perdido o nuestros errores. No se trata de borrar recuerdos ni de convencernos de que ‘fue para mejor’.`],what:`Vas a poner al lado de la historia que más se repite otra mirada que incluya lo que quedó afuera.`,before:[`Elegí una experiencia que puedas mirar hoy sin exigirte encontrar una conclusión.`],steps:[`Dividí la hoja en dos columnas: ‘LA HISTORIA QUE ESTOY RECORDANDO’ y ‘LA HISTORIA MÁS COMPLETA’.`,`En la primera anotá un pensamiento recurrente, por ejemplo: ‘Todo fue mi culpa’.`,`En la segunda agregá matices y hechos: ‘Puedo reconocer errores propios sin asumir responsabilidad por todo’.`,`Repetí con dos o tres recuerdos más. ‘Éramos muy felices’ puede convivir con ‘También había cosas que nos costaban’.`,`Leé ambas columnas. No reemplaces una historia negativa por una positiva; buscá una versión más completa.`],questions:[`¿Qué hechos estoy dejando afuera?`,`¿Qué recuerdo con más intensidad?`,`¿Qué estoy idealizando o demonizando?`,`¿Qué fue lindo realmente?`,`¿Qué fue difícil realmente?`,`¿Qué aprendí?`,`¿Qué necesito recordar cuando idealizo la situación?`],after:[`¿Qué columna fue más difícil de escribir?`,`¿Qué matiz apareció que antes no veía?`,`¿Qué parte aún no puedo saber con certeza?`],why:[`La memoria autobiográfica es reconstructiva y selectiva. El estado emocional puede influir en qué recordamos y cómo lo interpretamos.`,`Incluir información fuera de la narrativa dominante puede favorecer una perspectiva más flexible y matizada.`],yourWay:[`Usá dos colores, uno para cada columna.`,`Hacé dos páginas enfrentadas.`,`Escribí solo un recuerdo y un matiz.`]},{slug:`lo-pequeno-tambien-te-sostuvo`,title:`Lo pequeño también te sostuvo`,tagline:`Para mirar esas pequeñas cosas que ayudaron aunque no hayan resuelto todo.`,image:{version:1,asset_id:`6df0bcdf-736c-4a8d-9382-b608209f4404`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/6df0bcdf-736c-4a8d-9382-b608209f4404/nuevo-4.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/6df0bcdf-736c-4a8d-9382-b608209f4404/nuevo-4.webp`,original_filename:`nuevo-4.webp`,size:184738,content_type:`image/webp`,created_at:`2026-10-02T16:27:10Z`}.url,category:`crear`,categoryLabel:`Gratitud y evidencias`,topics:[`gratitud`],duration:`5–15 min`,minutes:10,accent:`verde`,intro:[`Cuando preguntarte ‘¿qué gran cosa buena pasó?’ te deja en blanco, cambiá la escala. Buscá microexperiencias de apoyo, alivio, conexión o cuidado sin negar lo difícil.`],what:`Vas a rodear una figura tuya con pequeñas cosas que estuvieron presentes.`,before:[`No busques algo espectacular. Una canción, una caminata o diez minutos de silencio alcanzan.`],steps:[`Dibujá en el centro una figura que te represente.`,`Trazá flechas alrededor.`,`En cada flecha escribí algo pequeño: una conversación, haber dicho que no, una comida rica, una noche de descanso o una emoción que pudiste nombrar.`,`Mirá el conjunto sin pedirle que resuelva todo.`,`Marcá una cosa que quieras recordar.`],questions:[`¿Qué hizo un día difícil apenas más llevadero?`,`¿Quién estuvo?`,`¿Qué gesto recuerdo?`,`¿Cuándo sentí un poco de calma?`,`¿Qué pude hacer por mí?`,`¿Qué funcionó aunque fuera diez minutos?`],after:[`¿Qué pequeña ayuda había pasado desapercibida?`,`¿Qué me gustaría repetir?`,`¿Qué todavía necesito además de esto?`],why:[`Dirigir la atención hacia experiencias pequeñas puede ampliar el registro de una etapa.`,`No niega las dificultades: incluye señales de apoyo y momentos de alivio que pueden quedar eclipsados por experiencias más intensas.`],yourWay:[`Usá stickers como flechas.`,`Pegá un recorte por cada gesto.`,`Hacé una lista breve sin dibujar la figura.`]},{slug:`sentate-con-tu-emocion`,title:`Sentate con tu emoción`,tagline:`Para cuando tu primera reacción es intentar que lo que sentís desaparezca.`,image:{version:1,asset_id:`8361d96c-ec78-4584-b113-78241e4456eb`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/8361d96c-ec78-4584-b113-78241e4456eb/nuevo-5.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/8361d96c-ec78-4584-b113-78241e4456eb/nuevo-5.webp`,original_filename:`nuevo-5.webp`,size:174538,content_type:`image/webp`,created_at:`2026-10-02T16:27:13Z`}.url,category:`pausar`,categoryLabel:`Emociones`,topics:[`emociones`,`conocerme`],duration:`5–10 min`,minutes:8,accent:`rosa`,intro:[`Observá una emoción durante unos minutos. No significa disfrutarla, resignarte ni permanecer en una situación dañina. Las emociones aportan información, pero necesitan contexto e interpretación.`],what:`Vas a dibujar dos sillas y explorar una emoción sin intentar eliminarla enseguida.`,before:[`Si observarla se siente demasiado intenso, podés parar o elegir algo más liviano.`],steps:[`Dibujá dos sillas. Una sos vos y la otra representa la emoción.`,`Escribí ‘Hoy me estoy sentando con…’ y nombrá lo que sentís, si podés.`,`Anotá dónde lo sentís en el cuerpo y qué pensamientos aparecen.`,`Preguntate qué necesidad podría estar señalando, sin tomar esa interpretación como verdad absoluta.`,`Elegí qué necesitás durante los próximos diez minutos.`],questions:[`¿Qué estoy sintiendo?`,`¿Dónde lo noto en el cuerpo?`,`¿Qué pensamiento aparece con esto?`,`¿Qué necesidad podría haber?`,`¿Qué pasa si no intento hacerlo desaparecer ya?`],after:[`¿Cambió algo al nombrarla?`,`¿Qué interpretación necesito revisar?`,`¿Qué cuidado pequeño puedo ofrecerme ahora?`],why:[`La atención consciente propone observar experiencias internas con menor reactividad inmediata.`,`Nombrar emociones y observar sensaciones puede favorecer la conciencia emocional y abrir una pausa entre sentir y actuar impulsivamente.`],yourWay:[`Escribí un diálogo corto entre las sillas.`,`Usá colores para cada silla.`,`Dibujá dos círculos en vez de sillas.`]},{slug:`el-semaforo`,title:`El semáforo: parar, observar, elegir`,tagline:`Para cuando sentís que estás por responder desde el impulso.`,image:{version:1,asset_id:`9bbee825-c4af-4c9e-b4ad-40df39205df2`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/9bbee825-c4af-4c9e-b4ad-40df39205df2/nuevo-6.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/9bbee825-c4af-4c9e-b4ad-40df39205df2/nuevo-6.webp`,original_filename:`nuevo-6.webp`,size:143232,content_type:`image/webp`,created_at:`2026-10-02T16:27:16Z`}.url,category:`pausar`,categoryLabel:`Pausa y decisiones`,topics:[`emociones`],duration:`5 min`,minutes:5,accent:`amarillo`,intro:[`Usá el semáforo como una metáfora práctica para hacer una pausa antes de responder. No es un protocolo clínico.`],what:`Vas a pasar por tres colores para detenerte, observar y elegir qué hacer.`,before:[`Si necesitás salir de una situación insegura, priorizá hacerlo; no hace falta completar la hoja primero.`],steps:[`Dibujá un semáforo con rojo, amarillo y verde.`,`ROJO · PARO: respiro, reconozco que estoy activada y recuerdo que no necesito responder inmediatamente.`,`AMARILLO · OBSERVO: ¿qué pasó?, ¿qué interpreté?, ¿qué siento?, ¿dónde lo noto?, ¿qué necesito?, ¿qué pasaría si actuara ahora?`,`VERDE · ELIJO: ¿quiero hablar, poner un límite, esperar, pedir ayuda, salir o no responder todavía?`,`Anotá la acción que se parezca más a la persona que querés ser.`],questions:[`¿Qué interpreté de lo que pasó?`,`¿Qué siento y qué necesito?`,`¿Qué consecuencias tendría responder ahora?`,`¿Puedo esperar unos minutos?`],after:[`¿Qué opción apareció al pausar?`,`¿Necesito más tiempo antes de actuar?`,`¿Hay alguien a quien pedir apoyo?`],why:[`Crear una pausa antes de responder puede ayudar a considerar alternativas a una reacción impulsiva.`,`Esta metáfora combina conciencia emocional, observación de pensamientos y elección deliberada de conducta.`],yourWay:[`Hacé tres círculos pequeños.`,`Usá papelitos rojo, amarillo y verde.`,`Escribí solo una palabra por color.`]},{slug:`lo-que-me-inquieta-y-lo-que-me-trae-calma`,title:`Lo que me inquieta / lo que me trae calma`,tagline:`Para empezar a reconocer patrones de activación y recursos que te hacen bien.`,image:{version:1,asset_id:`87aef9b2-eb33-4baa-af4d-6aa765c022f8`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/87aef9b2-eb33-4baa-af4d-6aa765c022f8/nuevo-7.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/87aef9b2-eb33-4baa-af4d-6aa765c022f8/nuevo-7.webp`,original_filename:`nuevo-7.webp`,size:94664,content_type:`image/webp`,created_at:`2026-10-02T16:27:19Z`}.url,category:`pausar`,categoryLabel:`Autoconocimiento`,topics:[`conocerme`,`emociones`],duration:`10 min`,minutes:10,accent:`verde`,intro:[`Separar contextos que te inquietan de cosas que te traen calma puede mostrar patrones propios. No todo se puede cambiar; buscá dónde hay un pequeño margen de acción.`],what:`Vas a escribir dos columnas y elegir un ajuste posible para vos.`,before:[`Pensá en situaciones concretas de estos días, no en cómo ‘deberías’ sentirte.`],steps:[`Dividí la hoja en ‘LO QUE ME INQUIETA’ y ‘LO QUE ME TRAE CALMA’.`,`A la izquierda anotá, si aplica: ruido, falta de sueño, pendientes, comparación, incertidumbre, conflictos o pantallas.`,`A la derecha anotá recursos propios: naturaleza, silencio, movimiento, escribir, música, compañía, tiempo a solas, leer o caminar.`,`Marcá con ○ algo que podés reducir y con ♡ algo que querés aumentar.`,`Preguntate: ‘¿Dónde tengo un pequeño margen de acción?’`],questions:[`¿Qué situaciones se repiten cuando me inquieto?`,`¿Qué me trae calma de verdad a mí?`,`¿Qué no depende de mí?`,`¿Cuál es un cambio pequeño posible?`],after:[`¿Qué patrón noté?`,`¿Qué recurso ya está a mi alcance?`,`¿Qué no necesito resolver hoy?`],why:[`Registrar contextos asociados a estados emocionales puede ayudar a reconocer patrones.`,`Conocerlos puede orientar decisiones preventivas y formas de autocuidado ajustadas a cada persona.`],yourWay:[`Dibujá símbolos en vez de palabras.`,`Hacé una página para cada lado.`,`Usá un color para lo que podés modificar.`]},{slug:`mis-metas-al-momento`,title:`Mis metas al momento`,tagline:`Para recordar qué querés construir y por qué realmente importa.`,image:{version:1,asset_id:`8b2e62e1-e6d8-4813-a920-f50e4e970b11`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/8b2e62e1-e6d8-4813-a920-f50e4e970b11/nuevo-8.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/8b2e62e1-e6d8-4813-a920-f50e4e970b11/nuevo-8.webp`,original_filename:`nuevo-8.webp`,size:122632,content_type:`image/webp`,created_at:`2026-10-02T16:27:22Z`}.url,category:`conocerme`,categoryLabel:`Metas e identidad`,topics:[`metas`],duration:`15–20 min`,minutes:18,accent:`lila`,intro:[`Esto no es una lista de productividad. El centro está en el significado que tiene cada meta para vos, no en cuánto hacés.`],what:`Vas a conectar cada meta actual con una razón personal para quererla.`,before:[`Podés incluir metas pequeñas, como descansar más, leer o tener tiempo para vos.`],steps:[`En el centro escribí ‘MIS METAS AL MOMENTO’.`,`Creá una burbuja por meta: mover el cuerpo, viajar, leer, crear, ahorrar, aprender o fortalecer un vínculo.`,`Debajo de CADA meta respondé ‘¿POR QUÉ ESTO ES IMPORTANTE PARA MÍ?’.`,`Por ejemplo, leer más puede significar pausa y curiosidad; viajar, libertad y experiencias nuevas.`,`Elegí una meta y pensá qué versión pequeña de ese valor podés vivir hoy.`],questions:[`¿Esta meta es realmente mía?`,`¿La seguiría queriendo si nadie la viera?`,`¿Qué valor representa?`,`¿Qué experiencia espero sentir?`,`¿Qué versión pequeña puedo empezar hoy?`],after:[`¿Qué metas comparten un valor?`,`¿Cuál se siente más propia?`,`¿Hay alguna expectativa que ya no quiero sostener?`],why:[`Las metas pueden sentirse más significativas cuando se vinculan con valores personales y razones propias.`,`Preguntar por qué ayuda a distinguir objetivos elegidos de expectativas que incorporamos sin revisarlas.`],yourWay:[`Pegá imágenes dentro de las burbujas.`,`Usá una flor con un pétalo por meta.`,`Elegí solo una meta y explorá varias razones.`]},{slug:`espiral-para-explorar-lo-que-siento`,title:`Espiral para explorar lo que siento`,tagline:`Una forma visual de ir desde ‘me siento rara’ hacia una comprensión un poco más específica.`,image:{version:1,asset_id:`4088ba68-584b-4a5f-b673-10d6bf4d05b7`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/4088ba68-584b-4a5f-b673-10d6bf4d05b7/nuevo-9.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/4088ba68-584b-4a5f-b673-10d6bf4d05b7/nuevo-9.webp`,original_filename:`nuevo-9.webp`,size:112808,content_type:`image/webp`,created_at:`2026-10-02T16:27:25Z`}.url,category:`escribir`,categoryLabel:`Emociones`,topics:[`emociones`,`conocerme`],duration:`10 min`,minutes:10,accent:`amarillo`,intro:[`La espiral es una propuesta visual de journaling, no una técnica clínica estandarizada. Podés sentir varias cosas a la vez y no siempre hay una causa única.`],what:`Vas a recorrer una espiral para distinguir sensación, emoción, contexto y necesidad.`,before:[`No encontrar una respuesta también es información. No busques precisión absoluta.`],steps:[`Dibujá una espiral grande. Desde afuera preguntate: ‘¿Cómo me siento?’.`,`En la siguiente vuelta: ‘¿Dónde lo siento en el cuerpo?’. Puede ser pecho, garganta, estómago, cabeza o mandíbula.`,`Después: ‘¿Qué emociones identifico?’. Quizá tristeza, miedo, enojo, alegría, confusión o varias a la vez.`,`Más adentro: ‘¿Qué pasó antes de sentirme así?’.`,`Seguí con: ‘¿Qué necesito atender?’ y ‘¿Qué puedo hacer ahora?’.`,`En el centro: ‘¿Qué puedo aprender de esta experiencia?’. Si no sabés todavía, también vale.`],questions:[`¿Qué palabra se acerca a lo que siento?`,`¿Qué noto en el cuerpo?`,`¿Hay más de una emoción?`,`¿Qué pasó antes?`,`¿Qué necesito ahora?`,`¿Qué no sé todavía?`],after:[`¿Pude diferenciar algo que antes sentía mezclado?`,`¿Qué pregunta sigue abierta?`,`¿Necesito apoyo de alguien?`],why:[`Distinguir sensaciones, emociones, antecedentes y necesidades puede aumentar la precisión con que reconocemos estados internos.`,`Eso puede facilitar respuestas más ajustadas que reaccionar solo desde una sensación global de malestar.`],yourWay:[`Usá un color por vuelta.`,`Escribí palabras sueltas.`,`Hacé la espiral de afuera hacia adentro o al revés.`],note:`No encontrar una respuesta también es información.`},{slug:`hoy-agradezco`,title:`Hoy agradezco`,tagline:`Para mirar algo de lo que sí estuvo presente hoy, incluso si el día también tuvo partes difíciles.`,image:{version:1,asset_id:`c372ed95-0dcd-4187-90de-6a3f2e2a2b61`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/c372ed95-0dcd-4187-90de-6a3f2e2a2b61/nuevo-10.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/c372ed95-0dcd-4187-90de-6a3f2e2a2b61/nuevo-10.webp`,original_filename:`nuevo-10.webp`,size:109036,content_type:`image/webp`,created_at:`2026-10-02T16:27:28Z`}.url,category:`crear`,categoryLabel:`Gratitud y evidencias`,topics:[`gratitud`],duration:`5–10 min`,minutes:8,accent:`rosa`,intro:[`Podés agradecer algo y seguir sintiéndote triste, cansada, enojada o confundida. Las dos experiencias pueden coexistir: la gratitud no invalida el malestar.`],what:`Vas a escribir ‘GRACIAS’ en el centro y rodearlo de detalles presentes en tu día.`,before:[`No tenés que encontrar nada extraordinario. Podés dejar espacios vacíos.`],steps:[`En el centro escribí ‘GRACIAS’.`,`Dibujá flechas hacia afuera.`,`Completá ‘Hoy agradezco…’: una conversación, comida, descanso, una persona, algo que aprendiste, tiempo con vos, haberlo intentado o algo que pudiste resolver.`,`Agregá una cosa pequeña que quieras recordar mañana.`,`Leé la página sin obligarte a sentirte diferente.`],questions:[`¿Qué estuvo bien durante unos minutos?`,`¿Qué funcionó hoy?`,`¿Qué disfruté?`,`¿Qué persona hizo una diferencia?`,`¿Qué pude hacer por mí?`,`¿Qué valoro de mi vida cotidiana?`,`¿Qué cosa pequeña quiero recordar mañana?`],after:[`¿Qué detalle no había notado?`,`¿Qué otras emociones siguen presentes?`,`¿Qué me gustaría recordar mañana?`],why:[`La atención no registra todo lo que ocurre con la misma prioridad. Las prácticas de gratitud dirigen parte de ella hacia experiencias valoradas.`,`No buscan sustituir emociones difíciles: proponen ampliar el registro de lo que ocurrió.`],yourWay:[`Dibujá un sol en vez de flechas.`,`Pegá papelitos con palabras.`,`Anotá solo una cosa de hoy.`],note:`Podés agradecer algo y seguir sintiéndote triste, cansada, enojada o confundida.`}],g=[{slug:`mapa-de-autoconocimiento`,title:`Mapa de autoconocimiento`,tagline:`Para mirarte en cinco partes: cualidades, momentos, logros, límites y metas.`,image:{version:1,asset_id:`38da00b9-136d-4c50-b2c0-373528074e55`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/38da00b9-136d-4c50-b2c0-373528074e55/nuevo-11.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/38da00b9-136d-4c50-b2c0-373528074e55/nuevo-11.webp`,original_filename:`nuevo-11.webp`,size:124096,content_type:`image/webp`,created_at:`2026-10-03T22:51:56Z`}.url,category:`conocerme`,categoryLabel:`Autoconocimiento`,topics:[`conocerme`,`metas`],duration:`20–30 min`,minutes:25,accent:`lila`,intro:[`A veces sabemos mucho de lo que nos falta y poco de lo que ya somos. Esta página reúne en un solo lugar distintas partes de tu historia y de tu presente.`],what:`Vas a dibujar cinco círculos y completar cada uno con una parte de vos.`,before:[`No hace falta llenar todo hoy. Podés empezar por el círculo que te resulte más fácil.`],steps:[`Escribí arriba ‘Autoconocimiento’.`,`Dibujá cinco círculos: CUALIDADES QUE IDENTIFICO DE MÍ · LOS EVENTOS MÁS IMPORTANTES DE MI VIDA · MIS LOGROS · MIS LÍMITES · MIS METAS.`,`Completá cada círculo con palabras sueltas o frases cortas.`,`En logros, incluí también cosas pequeñas o que nadie vio.`,`Al final, mirá la página completa y marcá lo que más te sorprende.`],questions:[`¿Qué cualidad me reconocen otras personas aunque yo dude?`,`¿Qué momento cambió la forma en que me veo?`,`¿Qué logré que antes me parecía imposible?`,`¿Qué ya no estoy dispuesta a aceptar?`,`¿Qué quiero construir en este momento?`],after:[`¿Qué círculo me costó más completar?`,`¿Hay alguna relación entre mis límites y mis metas?`,`¿Qué me gustaría recordar de esta página?`],why:[`Organizar información sobre vos en categorías puede facilitar una mirada más amplia del autoconcepto, que no se reduzca a una sola área o a un mal momento.`,`Registrar logros y límites también puede ayudar a reconocer valores y capacidades que ya están presentes.`],yourWay:[`Usá un color por círculo.`,`Pegá fotos o recortes en lugar de escribir.`,`Hacé un círculo por día durante una semana.`]},{slug:`rueda-de-las-emociones`,title:`Rueda de las emociones`,tagline:`Para darle forma y color a lo que estás sintiendo hoy.`,image:{version:1,asset_id:`836e29a8-a80c-478d-b803-3f4fc22de652`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/836e29a8-a80c-478d-b803-3f4fc22de652/nuevo-12.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/836e29a8-a80c-478d-b803-3f4fc22de652/nuevo-12.webp`,original_filename:`nuevo-12.webp`,size:134308,content_type:`image/webp`,created_at:`2026-10-03T22:51:58Z`}.url,category:`conocerme`,categoryLabel:`Emociones`,topics:[`emociones`,`creatividad`],duration:`10–15 min`,minutes:12,accent:`rosa`,intro:[`A veces sentimos varias cosas a la vez y es difícil decir cuál pesa más. La rueda te deja ver la mezcla sin elegir una sola emoción.`],what:`Vas a colorear una rueda dividida en emociones según cuánto está presente cada una hoy.`,before:[`No hay emociones buenas o malas en esta página. Todas pueden estar.`],steps:[`Dibujá un círculo grande con anillos concéntricos y dividilo en ocho partes.`,`Nombrá cada parte: Feliz, Asustada, Enojada, Disgustada, Triste, Amada, Aburrida, Preocupada (o las que quieras).`,`Pintá desde el centro hacia afuera: cuanto más presente está una emoción, más anillos coloreás.`,`Al lado de cada parte, escribí una palabra o situación que se relacione.`,`Mirá la forma final de tu rueda.`],questions:[`¿Qué emoción ocupa más lugar hoy?`,`¿Cuál casi no aparece?`,`¿Hay dos emociones que se mezclan?`,`¿Qué la despertó?`,`¿Dónde la siento en el cuerpo?`],after:[`¿Me sorprendió la forma de la rueda?`,`¿Qué necesito sabiendo esto?`,`¿Cómo se vería la rueda de otro día?`],why:[`Ponerle nombre a las emociones (etiquetado emocional) puede favorecer la conciencia emocional y una comprensión más precisa de lo que sentimos.`,`Ver varias emociones juntas ayuda a aceptar que pueden coexistir.`],yourWay:[`Usá solo cuatro emociones.`,`Repetí la rueda cada semana y comparalas.`,`Elegí tus propias palabras.`]},{slug:`zona-de-confort-y-zona-de-crecimiento`,title:`Mi zona de confort vs. mi zona de crecimiento`,tagline:`Para ver qué te da seguridad, qué te invita a crecer y dónde se cruzan.`,image:{version:1,asset_id:`6dbfb8c7-b3ce-4418-a6e4-dc9cc6d26da5`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/6dbfb8c7-b3ce-4418-a6e4-dc9cc6d26da5/nuevo-13.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/6dbfb8c7-b3ce-4418-a6e4-dc9cc6d26da5/nuevo-13.webp`,original_filename:`nuevo-13.webp`,size:118830,content_type:`image/webp`,created_at:`2026-10-03T22:52:00Z`}.url,category:`conocerme`,categoryLabel:`Metas e identidad`,topics:[`metas`,`conocerme`],duration:`15 min`,minutes:15,accent:`celeste`,intro:[`La zona de confort no es algo malo: es lo que te da seguridad. Esta página no busca que salgas de ella a la fuerza, sino ver qué hay en cada lado.`],what:`Vas a dibujar dos círculos que se cruzan y completar lo seguro, lo desafiante y lo que comparten.`,before:[`No necesitás decidir ningún cambio hoy. Solo vas a mirar.`],steps:[`Dibujá dos círculos que se superponen.`,`En uno escribí ‘Mi zona de confort’: lo que hoy se siente seguro y familiar.`,`En el otro ‘Mi zona de crecimiento’: lo que te ayudaría a crecer.`,`En el espacio compartido anotá lo que te desafía pero vale la pena.`,`Marcá una cosa del centro que te gustaría probar, por pequeña que sea.`],questions:[`¿Qué hago sin pensarlo porque me resulta conocido?`,`¿Qué me da curiosidad pero también miedo?`,`¿Qué cosa antes era difícil y hoy ya es parte de mi confort?`,`¿Qué paso pequeño podría dar?`],after:[`¿Qué lado se llenó más rápido?`,`¿Qué necesito para sentirme segura mientras pruebo algo nuevo?`],why:[`Distinguir lo familiar de lo desafiante puede ayudar a elegir desafíos manejables, algo relacionado con la autoeficacia.`,`Reconocer la seguridad como un recurso permite crecer sin desvalorizar lo que hoy te sostiene.`],yourWay:[`Usá un color para cada círculo.`,`Escribí solo tres cosas por zona.`,`Volvé a esta página en unos meses.`]},{slug:`no-todos-los-dias-son-buenos`,title:`No todos los días son buenos`,tagline:`Para escribir un día difícil sin tener que transformarlo en algo lindo.`,image:{version:1,asset_id:`25b4b392-1996-4d10-a82a-8f2c184755b6`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/25b4b392-1996-4d10-a82a-8f2c184755b6/nuevo-14.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/25b4b392-1996-4d10-a82a-8f2c184755b6/nuevo-14.webp`,original_filename:`nuevo-14.webp`,size:250762,content_type:`image/webp`,created_at:`2026-10-03T22:52:02Z`}.url,category:`escribir`,categoryLabel:`Emociones`,topics:[`emociones`,`gratitud`],duration:`10–20 min`,minutes:15,accent:`rosa`,intro:[`Hay días que simplemente cuestan. Esta página les hace lugar: podés contar lo que pasó y, si aparece, registrar también algo pequeño que estuvo.`],what:`Vas a escribir sobre un día difícil, con espacio para lo que sentiste y para lo que te acompañó.`,before:[`No tenés que encontrarle el lado bueno. Podés quedarte solo con lo difícil.`],steps:[`Poné la fecha arriba y una frase central grande: ‘No todos los días son buenos’.`,`Escribí cómo fue el día: ‘Hoy fue uno de esos días…’.`,`Agregá una frase que te acompañe, por ejemplo: ‘Está bien tener días así’.`,`Si querés, sumá un recuadro: ‘Aun así, hoy también hubo…’ (un café caliente, una canción, un mensaje).`,`Cerrá con algo para mañana, sin exigencias: ‘Mañana será otro día’.`],questions:[`¿Qué fue lo más pesado de hoy?`,`¿Qué sentí y no dije?`,`¿Qué me ayudó aunque sea un poco?`,`¿Qué necesito esta noche?`],after:[`¿Cómo me siento después de ponerlo en palabras?`,`¿Qué me diría si una amiga hubiera tenido este día?`],why:[`Escribir sobre experiencias difíciles puede ayudar a organizarlas y a mirarlas con algo de distancia.`,`Validar el malestar sin forzar positividad se relaciona con la aceptación emocional: lo difícil y lo pequeño que ayudó pueden convivir.`],yourWay:[`Dibujá una flor o un sticker en el centro.`,`Escribí solo tres líneas.`,`Usá colores apagados si así te sentís.`],note:`Podés agradecer algo y seguir sintiéndote cansada o triste. Las dos cosas pueden estar.`},{slug:`escribi-sin-pensar-ahora`,title:`Escribí sin pensar ahora`,tagline:`Para soltar la mano y dejar que salga lo que esté.`,image:{version:1,asset_id:`dc509ebe-ac24-4ddc-81ee-e3540b71b158`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/dc509ebe-ac24-4ddc-81ee-e3540b71b158/nuevo-15.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/dc509ebe-ac24-4ddc-81ee-e3540b71b158/nuevo-15.webp`,original_filename:`nuevo-15.webp`,size:296014,content_type:`image/webp`,created_at:`2026-10-03T22:52:04Z`}.url,category:`escribir`,categoryLabel:`Ordenar mi cabeza`,topics:[`ordenar`,`creatividad`],duration:`10 min`,minutes:10,accent:`amarillo`,intro:[`Escritura libre: sin corregir, sin ordenar, sin buscar que tenga sentido. Lo importante es no frenar la mano.`],what:`Vas a escribir sin parar durante unos minutos y, si querés, acompañarlo con un dibujo.`,before:[`Poné un temporizador de 5 a 10 minutos.`,`Nadie va a leer esto si no querés.`],steps:[`Escribí arriba ‘Escribí sin pensar ahora’.`,`Empezá con ‘Hoy me siento…’ y seguí sin frenar.`,`Si te trabás, escribí ‘no sé qué escribir’ hasta que aparezca otra cosa.`,`Cuando termine el tiempo, resaltá con color las palabras que más te llamen la atención.`,`Si querés, dibujá algo al lado: un retrato, formas, colores.`],questions:[`¿Qué tengo en la cabeza ahora mismo?`,`¿Qué me gustaría que pase?`,`¿Qué estoy sintiendo en el cuerpo?`],after:[`¿Qué palabras resalté?`,`¿Apareció algo que no esperaba?`],why:[`La escritura libre puede reducir la autocensura y facilitar que aparezcan pensamientos que en otro momento quedan tapados.`,`Resaltar después invita a una mirada metacognitiva: observar lo que escribiste.`],yourWay:[`Escribí en espiral o alrededor de un dibujo.`,`Usá lápices de colores distintos por minuto.`,`Hacelo en hojas sueltas.`]},{slug:`la-rueda-de-tu-vida`,title:`La rueda de tu vida`,tagline:`Para mirar cómo está cada área de tu vida en este momento.`,image:{version:1,asset_id:`39c6e24d-7c77-40ca-acc6-2c52228226dc`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/39c6e24d-7c77-40ca-acc6-2c52228226dc/nuevo-16.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/39c6e24d-7c77-40ca-acc6-2c52228226dc/nuevo-16.webp`,original_filename:`nuevo-16.webp`,size:130966,content_type:`image/webp`,created_at:`2026-10-03T22:52:05Z`}.url,category:`conocerme`,categoryLabel:`Metas e identidad`,topics:[`metas`,`conocerme`],duration:`15–20 min`,minutes:18,accent:`verde`,intro:[`Es una foto del momento, no una nota. Las áreas cambian y está bien que algunas tengan menos lugar en ciertas etapas.`],what:`Vas a puntuar del 1 al 10 cómo te sentís en cada área y colorear la rueda.`,before:[`Puntuá según cómo te sentís vos, no según lo que se espera.`],steps:[`Dibujá un círculo dividido en ocho partes con números del 1 al 10 desde el centro.`,`Nombrá las áreas: Desarrollo profesional, Salud, Finanzas, Crecimiento personal, Familia y amigos, Amor, Ocio, Hogar.`,`Pintá cada parte hasta el número que representa tu satisfacción hoy.`,`Mirá la forma: ¿qué áreas están más llenas y cuáles menos?`,`Elegí un área a la que te gustaría darle un poco más de atención.`],questions:[`¿Qué área me sorprendió?`,`¿Qué área tiene mucho espacio mental pero poco tiempo real?`,`¿Qué sería un punto más en esa área?`],after:[`¿Hay áreas que se relacionan entre sí?`,`¿Qué no quiero cambiar ahora y está bien?`],why:[`Mirar varias áreas a la vez puede ayudar a tomar perspectiva y a reconocer prioridades y valores.`,`Elegir un área concreta favorece metas manejables en lugar de querer cambiar todo.`],yourWay:[`Cambiá las áreas por las tuyas.`,`Usá colores pastel por área.`,`Repetila cada tres meses.`]},{slug:`collage-ponerle-orden-a-mi-cabeza`,title:`Collage: quiero ponerle orden a mi cabeza`,tagline:`Para expresar con recortes y frases lo que está pasando adentro.`,image:{version:1,asset_id:`fda76d77-5f71-4fb7-a4b1-d1d357b0896a`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/fda76d77-5f71-4fb7-a4b1-d1d357b0896a/nuevo-17.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/fda76d77-5f71-4fb7-a4b1-d1d357b0896a/nuevo-17.webp`,original_filename:`nuevo-17.webp`,size:211664,content_type:`image/webp`,created_at:`2026-10-03T22:52:07Z`}.url,category:`crear`,categoryLabel:`Creatividad`,topics:[`creatividad`,`ordenar`],duration:`20–40 min`,minutes:30,accent:`amarillo`,intro:[`A veces las palabras solas no alcanzan. Recortes, flores secas, papeles y frases pueden decir mucho de cómo estás.`],what:`Vas a armar un collage en una página y escribir una frase propia en la otra.`,before:[`Juntá revistas, papeles, washi tape, fotos o lo que tengas. No hace falta tener materiales especiales.`],steps:[`Elegí recortes que te llamen la atención sin pensar demasiado.`,`Pegalos en una página dejando que se superpongan.`,`Escribí frases cortas entre medio: lo que sentís, lo que pensás, lo que querés.`,`En la página de al lado escribí una sola frase grande, como ‘Quiero tener la valentía de ponerle orden a mi cabeza’.`,`Mirá el collage completo unos segundos.`],questions:[`¿Por qué elegí este recorte?`,`¿Qué frase me está acompañando estos días?`,`¿Qué quiero sentir?`],after:[`¿Qué me dice el collage que no había escrito?`,`¿Qué frase me llevo?`],why:[`Las actividades creativas pueden ofrecer otra vía para explorar y expresar experiencias internas.`,`Elegir imágenes y frases invita a prestar atención a lo que resuena con vos en este momento.`],yourWay:[`Usá solo papeles de colores.`,`Hacelo digital si no tenés revistas.`,`Armalo de a poco durante la semana.`]},{slug:`garabatea-sin-control`,title:`Garabateá sin control`,tagline:`Para cuando no hay palabras y solo necesitás mover la mano.`,image:{version:1,asset_id:`88deb9a1-09f0-4e23-8aca-490896a8df5d`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/88deb9a1-09f0-4e23-8aca-490896a8df5d/nuevo-18.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/88deb9a1-09f0-4e23-8aca-490896a8df5d/nuevo-18.webp`,original_filename:`nuevo-18.webp`,size:292604,content_type:`image/webp`,created_at:`2026-10-03T22:52:09Z`}.url,category:`pausar`,categoryLabel:`Para pausar`,topics:[`emociones`,`creatividad`],duration:`5 min`,minutes:5,accent:`rosa`,intro:[`No todo tiene que escribirse. A veces llenar una hoja de garabatos es una forma de descargar energía y bajar un cambio.`],what:`Vas a llenar una página de garabatos con colores, sin orden ni prolijidad.`,before:[`Elegí marcadores, crayones o lo que tengas a mano.`,`Está bien que quede ‘feo’.`],steps:[`Escribí arriba ‘Garabateá sin control, violentamente, sin orden ni prudencia’.`,`Agarrá un color y garabateá rápido sobre toda la hoja.`,`Cambiá de color cuando quieras.`,`Seguí hasta que sientas que alcanza.`,`Respirá y mirá la hoja.`],questions:[`¿Qué color elegí primero?`,`¿Cómo está mi cuerpo ahora?`,`¿Qué estaba sintiendo cuando empecé?`],after:[`¿Noto algo distinto en el cuerpo?`,`¿Quiero escribir algo ahora?`],why:[`El movimiento y la actividad sensorial pueden ayudar a dirigir la atención al presente.`,`Hacer algo sin objetivo de resultado puede bajar la autoexigencia y dar espacio a lo que se siente.`],yourWay:[`Hacelo con la mano no dominante.`,`Usá un solo color.`,`Garabateá con música.`]},{slug:`lo-que-depende-de-mi-y-lo-que-no`,title:`Lo que depende de mí y lo que no`,tagline:`Para separar lo que te hace sentir mal en lo que podés atender y lo que no.`,image:{version:1,asset_id:`e5b51225-a27b-4383-9d79-083441c4d243`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/e5b51225-a27b-4383-9d79-083441c4d243/nuevo-19.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/e5b51225-a27b-4383-9d79-083441c4d243/nuevo-19.webp`,original_filename:`nuevo-19.webp`,size:152258,content_type:`image/webp`,created_at:`2026-10-03T22:52:11Z`}.url,category:`ordenar`,categoryLabel:`Ordenar mi cabeza`,topics:[`ordenar`,`emociones`],duration:`15 min`,minutes:15,accent:`celeste`,intro:[`Muchas veces nos quedamos con malestares acumulados sin mirarlos. Esta página te invita a ponerlos afuera y distinguir qué está en tus manos.`],what:`Vas a responder ‘¿Qué cosas me están haciendo sentir mal?’ en dos columnas y buscar posibles soluciones.`,before:[`No hace falta resolver todo. Separar ya es un paso.`],steps:[`Escribí arriba la pregunta: ‘¿Qué cosas me están haciendo sentir mal?’.`,`Hacé dos recuadros: LAS COSAS QUE DEPENDEN DE MÍ y LAS QUE NO.`,`Anotá cada malestar en el recuadro que corresponda.`,`Abajo, en ‘Soluciones’, escribí un paso posible para alguna de las cosas que dependen de vos.`,`Para las que no dependen de vos, podés escribir cómo querés cuidarte mientras tanto.`],questions:[`¿Qué me viene preocupando hace días?`,`¿Qué parte de esto sí puedo atender?`,`¿Qué estoy intentando controlar que no depende de mí?`,`¿Qué paso pequeño podría dar?`],after:[`¿Qué recuadro se llenó más?`,`¿Qué siento al ver separadas las cosas?`],why:[`Externalizar preocupaciones puede ayudar a verlas con más claridad.`,`Distinguir lo controlable de lo que no lo es se relaciona con la flexibilidad cognitiva y con elegir dónde poner la energía.`],yourWay:[`Usá post-its que puedas mover.`,`Dos colores, uno por recuadro.`,`Hacelo cada domingo.`]},{slug:`lo-que-hay-en-mi-mente-ahora`,title:`Lo que hay en mi mente ahora`,tagline:`Para ver qué temas ocupan más lugar en tu cabeza, en un solo círculo.`,image:{version:1,asset_id:`8d62f659-eeed-4d9c-a4a0-b6b34d4e7302`,project_id:`f80f4743-8921-4ee6-b1ef-f8e75041e449`,url:`/__l5e/assets-v1/8d62f659-eeed-4d9c-a4a0-b6b34d4e7302/nuevo-20.webp`,r2_key:`a/v1/f80f4743-8921-4ee6-b1ef-f8e75041e449/8d62f659-eeed-4d9c-a4a0-b6b34d4e7302/nuevo-20.webp`,original_filename:`nuevo-20.webp`,size:161788,content_type:`image/webp`,created_at:`2026-10-03T22:52:13Z`}.url,category:`ordenar`,categoryLabel:`Ordenar mi cabeza`,topics:[`ordenar`,`creatividad`],duration:`15 min`,minutes:15,accent:`lila`,intro:[`Un círculo dividido como una torta, donde cada porción es un tema que hoy ocupa tu mente. Más grande la porción, más espacio ocupa.`],what:`Vas a dibujar un círculo con porciones para cada tema y decorarlas con patrones.`,before:[`Pensá en lo que ocupa tu mente, no en lo que debería ocuparla.`],steps:[`Escribí arriba ‘Lo que hay en mi mente ahora…’.`,`Hacé una lista de temas: trabajo, hijos, futuro, salud, plantas, autocuidado, arte, libros…`,`Dibujá un círculo y dividilo en porciones según cuánto lugar ocupa cada tema.`,`Asigná un patrón a cada tema (puntitos, rayas, corazones) y armá una leyenda abajo.`,`Llená cada porción con su patrón.`],questions:[`¿Qué tema ocupa la porción más grande?`,`¿Qué me gustaría que tuviera más lugar?`,`¿Hay algo que ocupa espacio y no es mío para resolver?`],after:[`¿Me sorprendió el tamaño de alguna porción?`,`¿Qué haría distinto si la dibujara la semana que viene?`],why:[`Representar visualmente las preocupaciones y temas puede facilitar la externalización y la toma de perspectiva.`,`Decorar con patrones suma un momento de atención tranquila en el presente.`],yourWay:[`Usá colores en lugar de patrones.`,`Hacé solo cinco porciones.`,`Repetila cada mes y compará.`]}],_=[{key:`todas`,label:`Todas`,emoji:`✦`},{key:`ordenar`,label:`Ordenar mi cabeza`,emoji:`☁`},{key:`emociones`,label:`Emociones`,emoji:`♡`},{key:`pausar`,label:`Para pausar`,emoji:`☾`},{key:`conocerme`,label:`Autoconocimiento`,emoji:`✧`},{key:`crear`,label:`Creatividad`,emoji:`✂`},{key:`gratitud`,label:`Gratitud y evidencias`,emoji:`✿`},{key:`metas`,label:`Metas e identidad`,emoji:`✎`},{key:`cerrar`,label:`Cerrar ciclos`,emoji:`↝`},{key:`mes`,label:`Cierre de mes`,emoji:`☀`}],v=[{slug:`todo-lo-que-esta-en-mi-cabeza`,title:`Todo lo que está en mi cabeza ahora`,tagline:`Para esos días en los que sentís que tu cabeza tiene veinte pestañas abiertas.`,category:`ordenar`,categoryLabel:`Descarga mental`,duration:`10–20 min`,minutes:15,image:e.url,accent:`rosa`,intro:[`Hay días en los que no tenemos “un problema”, pero sí demasiadas cosas abiertas al mismo tiempo: pendientes, ideas, personas, decisiones, planes, cosas que estamos evitando.`,`Este ejercicio propone sacar todo eso de la cabeza y ponerlo delante tuyo, en una hoja.`],what:`Vas a crear un mapa de todo lo que está ocupando espacio mental en este momento. No intentes ordenarlo primero: primero sacalo.`,steps:[`Agarrá una hoja y dibujá un garabato o nube en el centro: es tu cabeza.`,`Arriba escribí: “Todo lo que está en mi cabeza ahora”.`,`Alrededor armá cajitas con categorías: trabajo, pendientes, preocupaciones, personas, ideas, lo que siento, expectativas, cosas que me ilusionan.`,`Uní cada categoría al centro con una flecha.`,`Debajo de cada una escribí en lista todo lo que aparezca, sin filtro y sin orden.`,`Cuando termines, mirá la hoja completa y respirá: ya no tenés que sostenerlo todo de memoria.`],questions:[`¿Qué sigo recordándome mentalmente?`,`¿Qué estoy tratando de no olvidar?`,`¿Qué me preocupa?`,`¿Qué estoy anticipando?`,`¿Qué conversación tengo pendiente?`,`¿Qué decisión estoy evitando?`,`¿Qué idea sigue apareciendo?`,`¿Qué tengo ganas de hacer?`],why:[`Nuestra memoria de trabajo tiene una capacidad limitada. Cuando intentamos sostener tareas, preocupaciones e ideas al mismo tiempo, aumenta la sensación de carga mental.`,`Externalizar esa información (ponerla afuera, en papel) permite verla, organizarla y decidir con más claridad qué necesita atención.`,`Escribir no hace desaparecer los problemas, pero puede ayudarte a dejar de intentar recordarlos todos a la vez.`],yourWay:[`Usá un color distinto para cada categoría.`,`Escribí todo desordenado, sin cajitas.`,`Solo palabras sueltas: no hace falta armar frases.`]},{slug:`saco-todo-y-ahora-organizo`,title:`Saco todo de mi cabeza… y ahora organizo`,tagline:`Primero vaciás, después decidís qué hacer con cada cosa.`,category:`ordenar`,categoryLabel:`Descarga mental`,duration:`15–25 min`,minutes:20,image:t.url,accent:`lila`,intro:[`Esta versión usa las dos páginas del cuaderno: en la izquierda sacás todo, en la derecha lo ordenás.`,`Es ideal cuando sentís que tenés mil cosas y no sabés por cuál empezar.`],what:`Vas a hacer una descarga mental rápida y después vas a clasificar cada cosa en tres columnas: lo que puedo hacer hoy, lo que puede esperar y lo que no depende de mí.`,steps:[`En la página izquierda escribí: “Saco todo de mi cabeza” y debajo “¿Qué está ocupando espacio en mi cabeza ahora?”.`,`Hacé un garabato en el centro y rodealo con burbujas: trabajo, pendientes, preocupaciones, cosas que tengo que resolver, decisiones, planes, ideas.`,`Llená cada burbuja con lo que aparezca, sin pensar demasiado.`,`En la página derecha escribí “Ahora organizo” y dibujá tres columnas: PUEDO HACER ALGO HOY · PUEDE ESPERAR · NO DEPENDE DE MÍ.`,`Pasá cada cosa de la izquierda a una de las columnas.`,`Abajo, en un recuadro, respondé: “¿Cómo me siento ahora?”.`],questions:[`¿Qué de todo esto podría resolver en 10 minutos?`,`¿Qué estoy cargando que en realidad no depende de mí?`,`¿Qué puede esperar sin que pase nada grave?`,`¿Cuál es la ÚNICA cosa que haría hoy?`,`¿Cómo me siento después de verlo todo en papel?`],why:[`Separar lo que está bajo tu control de lo que no lo está ayuda a dirigir la energía hacia acciones posibles, en lugar de dar vueltas sobre lo que no podés cambiar.`,`Clasificar también reduce la cantidad de decisiones pendientes que tu mente intenta sostener al mismo tiempo.`],yourWay:[`Usá post-its y movelos entre columnas.`,`Pintá cada columna con un resaltador distinto.`,`Hacelo solo con una lista y tres símbolos: ✓ → ✗.`]},{slug:`que-esta-ocupando-espacio-hoy`,title:`¿Qué está ocupando espacio en mi cabeza hoy?`,tagline:`Un chequeo rápido para empezar el día más liviana.`,category:`ordenar`,categoryLabel:`Chequeo diario`,duration:`5–10 min`,minutes:8,image:u.url,accent:`verde`,intro:[`No siempre tenés tiempo para una página enorme. Esta es la versión exprés: una pregunta y unos minutos.`,`Funciona muy bien a la mañana con el café o a la noche antes de dormir.`],what:`Vas a hacer una foto de tu cabeza HOY: pensamientos, emociones, cosas que querés y lo que no querés olvidar.`,steps:[`Escribí arriba la pregunta: “¿Qué está ocupando espacio en mi cabeza hoy?”.`,`Dibujá un garabato chiquito en el centro.`,`Elegí 6 a 8 cajitas: trabajo, pensamientos, emociones, personas, cosas pendientes, lo que me preocupa, cosas que quiero, lo que no quiero olvidar.`,`Escribí 2 o 3 cosas por cajita. Rápido, sin pensar demasiado.`,`Marcá con un corazón lo que te hace bien y con un círculo lo que necesita atención hoy.`],questions:[`¿Qué pensamiento se repite desde que me desperté?`,`¿Qué emoción tiene más volumen hoy?`,`¿Qué quiero que pase hoy?`,`¿Qué no quiero olvidar?`,`¿Qué necesito soltar por hoy?`],why:[`Ponerle nombre a lo que pensás y sentís favorece la conciencia emocional: notar qué está pasando antes de reaccionar en automático.`,`Hacerlo como hábito breve suma más que una página perfecta una vez por mes.`],yourWay:[`Hacelo todos los días en una página pequeña.`,`Usá solo emojis y palabras.`,`Escribilo en el celular y pasalo al cuaderno a la noche.`]},{slug:`descarga-con-recordatorio`,title:`Descarga mental con recordatorio para mí`,tagline:`Vaciás la cabeza, ordenás y terminás con una nota amable para vos.`,category:`escribir`,categoryLabel:`Descarga mental`,duration:`20 min`,minutes:20,image:d.url,accent:`rosa`,intro:[`A veces después de ordenar todo queda una sensación de “uf, cuánto”.`,`Esta versión agrega un último paso: escribirte un recordatorio, como lo haría una amiga.`],what:`Vas a hacer el mapa de todo lo que está en tu cabeza, lo vas a ordenar por columnas y vas a cerrar con un mensaje para vos.`,steps:[`En el centro escribí: “¿Qué está ocupando espacio en mi cabeza ahora?”.`,`Alrededor: mi casa, mi familia, mi relación, mi salud, dinero, cosas que quiero hacer, cosas que me preocupan, cosas que me ilusionan.`,`En la otra página escribí “Ahora organizo” con tres columnas con casilleros: puedo hacer algo hoy · puede esperar · no depende de mí.`,`Tachá (o tildá) lo que ya podés resolver.`,`Respondé: “¿Cómo me siento ahora?”.`,`En un recuadro final titulado “Recordatorio” escribite algo amable. Ejemplo: “Mi mente no tiene que sostener todo. Escribir me ayuda a liberar carga mental”.`],questions:[`¿Qué me diría una amiga que me quiere si viera esta página?`,`¿Qué necesito escuchar hoy?`,`¿Qué parte de todo esto ya estoy haciendo bien?`,`¿Qué me puedo permitir no resolver hoy?`],why:[`Hablarte con amabilidad (autocompasión) no es ser blanda: diversos estudios lo relacionan con más motivación para seguir intentando después de un tropiezo.`,`Cerrar con un mensaje compasivo ayuda a que la página no termine en una lista de exigencias.`],yourWay:[`Escribí el recordatorio en un papel aparte y pegalo en tu espejo.`,`Hacelo en forma de carta.`,`Dibujá en lugar de escribir el recordatorio.`]},{slug:`ahora-observo`,title:`Todo lo que está en mi cabeza… ahora observo`,tagline:`Escribir, mirar desde afuera y notar cómo te sentís después.`,category:`conocerme`,categoryLabel:`Observar mis pensamientos`,duration:`15–20 min`,minutes:15,image:f.url,accent:`amarillo`,intro:[`Esta versión agrega algo muy valioso: mirar tu propia página como si fuera de otra persona.`,`No para juzgarla, sino para observar.`],what:`Vas a hacer tu mapa mental y después vas a mirarlo con curiosidad: ¿qué ves?, ¿cómo te sentís después de escribirlo?`,steps:[`Escribí en el centro: “¿Qué está ocupando espacio en mi cabeza?”.`,`Rodealo con categorías: trabajo, casa, mi salud, personas, ideas, metas, emociones, lo que me preocupa, cosas que no quiero olvidar.`,`En la otra página escribí: “Ahora observo…”.`,`Hacé tres columnas: puedo hacer algo hoy · puede esperar · no depende de mí.`,`Abajo respondé: “¿Cómo me siento después de escribirlo?”.`,`Cerrá con una frase que resuma lo que notaste.`],questions:[`¿Qué categoría tiene más cosas?`,`¿Qué me sorprendió ver escrito?`,`¿Qué tema se repite en varias cajitas?`,`¿Cómo me sentía antes de escribir y cómo me siento ahora?`,`Si fuera la página de una amiga, ¿qué le diría?`],why:[`Observar tus propios pensamientos con algo de distancia es una forma de metacognición: pensar sobre lo que pensás.`,`Esa distancia permite notar patrones y elegir respuestas en vez de solo reaccionar.`],yourWay:[`Volvé a mirar la página al día siguiente y anotá algo nuevo.`,`Marcá con flechas las cosas que se conectan entre sí.`,`Agregá un dibujo de cómo te sentís.`]},{slug:`lo-que-puedo-lograr-y-lo-que-me-genera-ansiedad`,title:`Lo que puedo lograr y lo que me genera ansiedad`,tagline:`Para separar lo que te da energía de lo que te la quita.`,category:`ordenar`,categoryLabel:`Ordenar emociones`,duration:`15 min`,minutes:15,image:p.url,accent:`celeste`,intro:[`Dentro de la cabeza todo se mezcla: lo que nos entusiasma, lo que nos asusta y lo que nos da curiosidad.`,`Esta página te ayuda a separarlo.`],what:`Vas a hacer tu mapa y después vas a reagruparlo en: algo que puedo lograr, algo que me genera ansiedad, algo que no quiero olvidar y algo que me da curiosidad.`,steps:[`Escribí en una nube central: “Todo lo que está ocupando espacio en mi cabeza ahora”.`,`A la izquierda: trabajo, pendientes, personas, ideas/proyectos.`,`A la derecha: cosas que me preocupan, algo que estoy evitando, cosas que no quiero olvidar.`,`En la otra página escribí cuatro títulos: algo que puedo lograr · algo que me genera ansiedad · algo que no quiero olvidar · algo que me da curiosidad.`,`Repartí todo en esas cuatro zonas.`,`Elegí UNA cosa de “puedo lograr” para hacer esta semana.`],questions:[`¿Qué me gustaría lograr aunque sea en pequeño?`,`¿Qué me genera ansiedad cuando lo pienso?`,`¿Qué parte de esa ansiedad es anticipación?`,`¿Qué me da curiosidad últimamente?`,`¿Qué estoy evitando y por qué?`],why:[`Diferenciar emociones (ansiedad, entusiasmo, curiosidad) en lugar de sentir “todo junto” se relaciona con una mejor regulación emocional.`,`Elegir una acción concreta y alcanzable puede fortalecer la sensación de autoeficacia: “puedo hacer algo con esto”.`],yourWay:[`Usá un color para cada emoción.`,`Dibujá las cuatro zonas como cuatro frascos.`,`Hacelo con stickers o símbolos.`]},{slug:`lo-que-necesito-decidir-y-lo-que-me-hace-bien`,title:`Lo que necesito decidir y lo que me hace bien`,tagline:`Un mapa completo que no se queda solo en lo pendiente.`,category:`conocerme`,categoryLabel:`Mapa completo`,duration:`20–30 min`,minutes:25,image:m.url,accent:`lila`,intro:[`Muchos mapas mentales se llenan solo de problemas y pendientes.`,`Este también hace lugar para lo que te hace bien, tus planes y tu cuerpo.`],what:`Vas a armar un mapa grande que equilibre lo que te pesa con lo que te sostiene.`,steps:[`Arriba escribí: “Todo lo que está en mi cabeza ahora” y dibujá un garabato en el centro.`,`Arriba del garabato: trabajo, pendientes, lo que me preocupa.`,`A los costados: personas, ideas, planes.`,`Abajo: cosas que estoy evitando, lo que necesito decidir.`,`Y muy importante, agregá: lo que me hace bien, cuerpo y salud, cosas que no quiero olvidar.`,`Cuando termines, compará: ¿cuánto espacio ocupa lo que te pesa y cuánto lo que te hace bien?`],questions:[`¿Qué decisión vengo postergando?`,`¿Cuál sería el próximo paso más pequeño para decidir?`,`¿Qué me hace bien y lo estoy dejando de lado?`,`¿Cómo está mi cuerpo hoy?`,`¿Qué planes me entusiasman?`],why:[`Cuando estamos cargadas, la atención se va casi sola hacia lo amenazante o pendiente. Incluir deliberadamente lo que te hace bien amplía el foco.`,`Ver las decisiones escritas, separadas del resto, ayuda a enfrentarlas de a una.`],yourWay:[`Pintá lo que te hace bien con colores cálidos.`,`Pegá una foto en “lo que me hace bien”.`,`Hacé solo las categorías que necesites hoy.`]},{slug:`un-mes-en-fotos`,title:`Un mes en fotos`,tagline:`Una foto por día para poder mirar todo lo que también pasó.`,category:`mes`,categoryLabel:`Cerrar el mes`,duration:`Todo el mes · 30 min al final`,minutes:30,image:n.url,accent:`rosa`,canva:`https://canva.link/qjqc5qejhrhh012`,intro:[`La idea es guardar una pequeña evidencia visual de cada día. No tiene que ser el mejor momento ni algo extraordinario.`,`Al terminar el mes, todas esas imágenes juntas cuentan una historia que difícilmente podrías reconstruir solo desde la memoria.`],what:`Vas a armar un calendario del mes con una mini foto en cada día, más un espacio para tu momento favorito.`,steps:[`Cada día sacá una foto: un desayuno, el cielo, tu mascota, una caminata, tu escritorio, un atardecer o un día completamente normal.`,`Al final del mes elegí una foto por día.`,`Imprimilas chiquitas (o usá la plantilla de Canva).`,`Dibujá o pegá la cuadrícula del calendario en tu cuaderno y pegá cada foto en su día.`,`Abajo, elegí tu momento favorito del mes y escribí por qué.`,`Decorá con washi tape, corazones o flores secas si te dan ganas.`],questions:[`¿Qué foto me hace sonreír más?`,`¿Qué día parecía normal y ahora me gusta recordar?`,`¿Cuál fue mi momento favorito del mes?`,`¿Qué se repite en mis fotos?`,`¿Qué quiero fotografiar más el mes que viene?`],why:[`La memoria no funciona como una grabación: retiene algunos momentos y otros se pierden rápido.`,`Registrar un detalle por día ayuda a recuperar experiencias pequeñas y a construir un recuerdo más rico y realista del mes.`],yourWay:[`Pegá tickets, envoltorios o una flor seca en lugar de fotos.`,`Escribí una sola palabra por día.`,`Hacé un collage gigante en vez de calendario. Tu mes no tiene que quedar ordenado para ser valioso.`]},{slug:`el-sol-de-mi-mes`,title:`Mi mes en un vistazo`,tagline:`Un sol con todo lo que te dejó el mes, mucho más que metas cumplidas.`,category:`mes`,categoryLabel:`Cerrar el mes`,duration:`20–30 min`,minutes:25,image:r.url,accent:`amarillo`,intro:[`Una forma creativa de mirar un mes completo sin reducirlo solamente a metas cumplidas.`,`Al final, tu página parece un sol que irradia todo lo que viviste.`],what:`Vas a dibujar un sol con el nombre del mes en el centro y escribir un recuerdo o reflexión en cada rayo.`,steps:[`En el centro de la hoja dibujá un círculo y escribí el nombre del mes.`,`Desde el círculo trazá muchos rayos hacia afuera.`,`En cada rayo escribí algo: algo que aprendí, algo que disfruté, algo difícil, una persona importante, algo que agradezco.`,`Sumá: algo que hice por primera vez, algo de lo que estoy orgullosa, un hábito que sostuve.`,`Agregá dibujitos pequeños entre los rayos.`,`Terminá con: “algo que quiero llevarme al próximo mes”.`],questions:[`¿Qué pasó este mes que no quiero olvidar?`,`¿Qué me sorprendió?`,`¿Qué cambió en mí?`,`¿Qué disfruté?`,`¿De qué estoy orgullosa?`,`¿Qué aprendí?`],why:[`Hacer una revisión deliberada del mes ayuda a recuperar experiencias que podrían pasar desapercibidas.`,`Incluir aprendizajes y momentos difíciles (no solo logros) da una mirada más justa y completa de tu proceso.`],yourWay:[`Pintá el sol con acuarela.`,`Pegá mini fotos en algunos rayos.`,`Usá una flor en lugar de un sol, un pétalo por recuerdo.`]},{slug:`cosas-que-me-dan-rabia`,title:`Cosas que me dan rabia`,tagline:`Para ponerle palabras a lo que te irrita, molesta o enoja.`,category:`escribir`,categoryLabel:`Emociones`,duration:`10–20 min`,minutes:15,image:i.url,accent:`rosa`,intro:[`No tenés que escribir de forma correcta, madura ni razonable.`,`Esta página es para sacar. Primero observás; después, si querés, entendés.`],what:`Vas a escribir sin censura todo lo que te da rabia y después vas a buscar qué información trae ese enojo.`,steps:[`En el centro escribí bien grande: “Cosas que me dan rabia” (podés usar letras recortadas de revistas).`,`Alrededor sacá todo: personas, situaciones, comentarios, injusticias, ruido, redes sociales, cosas que no salen, interrupciones.`,`No te censures mientras escribís. Llená la hoja si hace falta.`,`Cuando termines, frená y mirá la página.`,`Subrayá los temas que aparecen varias veces.`,`Escribí en un costado qué necesitás o qué límite podrías poner.`],questions:[`¿Qué temas aparecen varias veces?`,`¿Qué necesito?`,`¿Hay algún límite que no estoy poniendo?`,`¿Qué sí puedo hacer?`,`¿Qué simplemente necesito reconocer?`],why:[`Nombrar una emoción facilita identificarla y diferenciarla de otras.`,`Mirar patrones de enojo puede darte información valiosa sobre tus expectativas, necesidades y límites. El objetivo no es “eliminar” el enojo, sino entender qué te está diciendo.`],yourWay:[`Escribí con letras recortadas, estilo carta anónima.`,`Usá un marcador fuerte y apretá todo lo que quieras.`,`Escribí en una hoja suelta y después rompela si te hace bien.`]},{slug:`esta-bien-si-demora`,title:`Está bien si demora más de lo que esperabas`,tagline:`Para revisar los plazos que te estás imponiendo.`,category:`pausar`,categoryLabel:`Paciencia con mi proceso`,duration:`15–20 min`,minutes:15,image:a.url,accent:`verde`,intro:[`“A esta edad debería…”, “ya tendría que…”. Muchas expectativas de tiempo funcionan como reglas que nunca revisamos.`,`Esta página es para mirarlas con un poco más de cariño.`],what:`Vas a escribir una frase central amable y alrededor vas a revisar qué esperabas, qué sí pasó y qué aprendiste.`,steps:[`En el centro escribí: “Está bien si demora más de lo que esperaba”. Podés recortar las letras o pegarlas en papelitos.`,`Alrededor pegá papelitos de colores con respuestas a: ¿qué pensé que ya tendría resuelto?`,`¿Qué progreso sí ocurrió?`,`¿Qué aprendí durante este tiempo?`,`¿Qué cosas necesitan más tiempo?`,`Terminá con: “¿Qué ritmo sería sostenible para mí?”.`],questions:[`¿Quién decidió que ya debería haber llegado?`,`¿Estoy comparando mi proceso con el de alguien más?`,`¿Qué evidencia tengo de que “voy tarde”?`,`¿Qué estoy aprendiendo mientras avanzo?`],why:[`Hacer explícitas las expectativas de tiempo permite evaluarlas con distancia en lugar de obedecerlas en automático.`,`Esto se relaciona con la reevaluación cognitiva: mirar una situación desde otra interpretación más flexible.`],yourWay:[`Hacelo collage con papeles, washi tape y flores.`,`Escribí frases cortas en tiritas de papel.`,`Pegá una foto de algo que te costó y lograste.`]},{slug:`cosas-que-quiero-aprender`,title:`Cosas que quiero aprender`,tagline:`Para volver a conectar con la curiosidad, sin que todo tenga que ser productivo.`,category:`crear`,categoryLabel:`Curiosidad`,duration:`15–25 min`,minutes:20,image:o.url,accent:`verde`,intro:[`No todo lo que aprendemos necesita convertirse en trabajo o dinero.`,`Podés aprender algo solamente porque te interesa.`],what:`Vas a armar un mapa de cosas que te gustaría aprender, con un pequeño detalle de qué querés saber de cada una.`,steps:[`En el centro escribí bien colorido: “Cosas que quiero aprender”.`,`Creá ramas o recuadros: lettering, fotografía, psicología, técnicas de journal, edición, cocina, idiomas, manejar.`,`Debajo de cada tema escribí qué te gustaría saber hacer exactamente.`,`Agregá un dibujito para cada tema.`,`Sumá un recuadro “otras habilidades” para ideas sueltas.`,`Marcá con una estrella la que te gustaría empezar este mes.`],questions:[`¿Qué tema siempre termina llamando mi atención?`,`¿Qué me gustaría saber hacer solamente por diversión?`,`¿Qué habilidad me daría más independencia?`,`¿Qué tengo curiosidad por probar?`,`¿Qué aprendería aunque nadie lo viera?`],why:[`La curiosidad y la motivación intrínseca (hacer algo porque sí, porque te gusta) favorecen la exploración.`,`Separar aprendizaje de rendimiento permite recuperar una relación más lúdica con aprender.`],yourWay:[`Pegá imágenes de revistas de cada tema.`,`Anotá nombres de cursos o videos para mirar después.`,`Dibujá cada habilidad como una planta que va a crecer.`]},{slug:`no-tengo-que-tenerlo-todo-resuelto`,title:`No tengo que tenerlo todo resuelto para empezar`,tagline:`Para cuando estás esperando sentirte totalmente segura antes de arrancar.`,category:`pausar`,categoryLabel:`Empezar con dudas`,duration:`10–20 min`,minutes:15,image:s.url,accent:`amarillo`,intro:[`A veces no empezamos porque sentimos que todavía no sabemos lo suficiente.`,`Esta página te recuerda que se puede empezar con dudas.`],what:`Vas a crear una página-collage con una frase central y pensamientos que te den permiso para dar un primer paso pequeño.`,steps:[`En el centro, sobre un papel rasgado, escribí: “No tengo que tenerlo todo resuelto para empezar”.`,`Alrededor pegá papelitos con frases como: “Puedo empezar aunque tenga dudas”, “No necesito conocer todo el camino”.`,`Sumá: “Puedo aprender mientras avanzo”, “Puedo equivocarme”, “Paso a paso también se llega lejos”.`,`Agregá fotos, flores secas, mariposas o lo que tengas a mano.`,`En un costado escribí: “¿Qué puedo empezar con la información que tengo hoy?”.`,`Respondé con una acción MUY pequeña.`],questions:[`¿Qué estoy esperando saber?`,`¿Qué certeza estoy buscando?`,`¿Qué puedo descubrir solamente haciendo?`,`¿Cuál sería una versión muy pequeña del primer paso?`],why:[`La necesidad de certeza puede aumentar la postergación cuando una decisión tiene muchas variables desconocidas.`,`Pasar de una decisión enorme a una acción pequeña te da información nueva a través de la experiencia, y eso puede fortalecer la sensación de capacidad.`],yourWay:[`Usá papel de diario o de bolsas para el collage.`,`Escribí las frases en tu propia letra, aunque no te guste.`,`Hacé una versión chiquita para llevar en tu billetera.`]},{slug:`ocurrencias-mias-de-la-a-a-la-z`,title:`Ocurrencias mías de la A a la Z`,tagline:`Conocerte a través de tus costumbres, rarezas y gustos. ¡Divertido de verdad!`,category:`conocerme`,categoryLabel:`Autoconocimiento lúdico`,duration:`20–30 min`,minutes:25,image:c.url,accent:`lila`,intro:[`No todo en journaling tiene que ser profundo.`,`También podemos conocernos mirando nuestras pequeñas manías y formas de ser.`],what:`Vas a escribir el abecedario y, para cada letra, algo sobre vos: una costumbre, un gusto, una contradicción, una rareza.`,steps:[`Escribí el título: “Ocurrencias mías de la A a la Z”.`,`Escribí las letras del abecedario en una columna (podés usar dos páginas).`,`Para cada letra escribí algo tuyo. Ej: “A: amo las listas aunque nunca las termine”.`,`Si una letra se traba, saltéala y volvé después.`,`Sumá dibujitos o íconos al lado de las frases.`,`Al final, leelo entero y marcá tu favorita.`],questions:[`¿Qué hago siempre aunque nadie lo sepa?`,`¿Qué me encanta y me da un poco de vergüenza?`,`¿En qué soy contradictoria?`,`¿Qué manía tengo?`,`¿Qué cosa chiquita me hace feliz?`],why:[`El autoconocimiento no solo se construye con preguntas profundas: observar costumbres y gustos también aporta información sobre quién sos.`,`Hacerlo desde el humor permite explorar tu identidad desde un lugar liviano y amable.`],yourWay:[`Hacelo con amigas y compartan sus letras.`,`Usá un color por letra.`,`Hacé una versión: “Cosas que amo de la A a la Z”.`]},{slug:`estoy-agradecida-por`,title:`Estoy agradecida por…`,tagline:`Una página para prestar atención a cosas concretas que valorás.`,category:`crear`,categoryLabel:`Gratitud`,duration:`10–15 min`,minutes:12,image:l.url,accent:`amarillo`,intro:[`No se trata de obligarte a estar agradecida cuando estás pasando por algo difícil.`,`Podés tener un día complicado y, al mismo tiempo, encontrar algo pequeño que valorás.`],what:`Vas a hacer un garabato colorido en el centro y desde ahí flechas hacia todo lo que agradecés.`,steps:[`Arriba escribí con colores: “Estoy agradecida por”.`,`En el centro hacé un garabato grande y pintá cada espacio de un color distinto.`,`Desde el garabato dibujá flechas hacia afuera.`,`En la punta de cada flecha escribí algo: mi casa, mi familia, el café, mis amigas, el sol, mi cuerpo.`,`Sumá cosas pequeñas y cotidianas, no solo las grandes.`,`Agregá un dibujito al lado de cada palabra.`],questions:[`¿Qué hizo mi día un poquito mejor?`,`¿Qué persona agradezco tener cerca?`,`¿Qué cosa cotidiana suelo dar por sentada?`,`¿Qué disfruté últimamente?`,`¿Qué parte de mi vida actual alguna vez deseé tener?`],why:[`Las prácticas de gratitud dirigen deliberadamente la atención hacia experiencias valoradas, que muchas veces quedan tapadas por problemas o pendientes.`,`El objetivo no es negar lo difícil, sino ampliar aquello a lo que también prestás atención.`],yourWay:[`Escribí veinte cosas o solamente tres.`,`Pegá fotos de las personas o lugares.`,`Hacé una nube en lugar de flechas.`]}];v.push(...h,...g);function y(e,t){if(t===`todas`)return!0;let n=[e.category,...e.topics??[]];return t===`emociones`?n.includes(`emociones`)||[`cosas-que-me-dan-rabia`,`lo-que-puedo-lograr-y-lo-que-me-genera-ansiedad`].includes(e.slug):t===`gratitud`?n.includes(`gratitud`)||e.slug===`estoy-agradecida-por`:t===`metas`?n.includes(`metas`)||[`cosas-que-quiero-aprender`,`no-tengo-que-tenerlo-todo-resuelto`].includes(e.slug):t===`cerrar`?n.includes(`cerrar`)||e.slug===`esta-bien-si-demora`:t===`crear`?n.includes(`creatividad`)||e.category===`crear`:t===`conocerme`?n.includes(`conocerme`)||e.category===`conocerme`:t===`ordenar`?e.category===`ordenar`||e.slug===`descarga-con-recordatorio`:n.includes(t)}var b=e=>v.find(t=>t.slug===e);export{y as i,v as n,b as r,_ as t};